35|/** Delegation token receiver for S3 filesystems. */
36|@Internal
37|public abstract class AbstractS3DelegationTokenReceiver implements DelegationTokenReceiver {
38|
39|    public static final String PROVIDER_CONFIG_NAME = "fs.s3a.aws.credentials.provider";
40|
41|    private static final Logger LOG =
42|            LoggerFactory.getLogger(AbstractS3DelegationTokenReceiver.class);
43|
44|    @VisibleForTesting @Nullable static volatile Credentials credentials;
45|
46|    @VisibleForTesting @Nullable static volatile String region;
47|
48|    public static void updateHadoopConfig(org.apache.hadoop.conf.Configuration hadoopConfig) {
49|        LOG.info("Updating Hadoop configuration");
50|
51|        String providers = hadoopConfig.get(PROVIDER_CONFIG_NAME, "");
52|        if (!providers.contains(DynamicTemporaryAWSCredentialsProvider.NAME)) {
53|            if (providers.isEmpty()) {
54|                LOG.debug("Setting provider");
55|                providers = DynamicTemporaryAWSCredentialsProvider.NAME;
56|            } else {
57|                providers = DynamicTemporaryAWSCredentialsProvider.NAME + "," + providers;
58|                LOG.debug("Prepending provider, new providers value: {}", providers);
59|            }
60|            hadoopConfig.set(PROVIDER_CONFIG_NAME, providers);
61|        } else {
62|            LOG.debug("Provider already exists");
63|        }
64|
65|        if (!StringUtils.isNullOrWhitespaceOnly(region)) {
66|            LOG.debug("Setting region");
67|            hadoopConfig.set("fs.s3a.endpoint.region", region);
68|        }
69|
70|        LOG.info("Updated Hadoop configuration successfully");
71|    }
72|
73|    @Override
74|    public void init(Configuration configuration) {
75|        region =
76|                configuration.getString(
77|                        String.format(
78|                                "%s.%s.region",
79|                                DelegationTokenProvider.CONFIG_PREFIX, serviceName()),
80|                        null);
81|        if (!StringUtils.isNullOrWhitespaceOnly(region)) {
82|            LOG.debug("Region: " + region);
83|        }
84|    }
85|
86|    @Override
87|    public void onNewTokensObtained(byte[] tokens) throws Exception {
88|        LOG.info("Updating session credentials");
89|        credentials =
90|                InstantiationUtil.deserializeObject(
91|                        tokens, AbstractS3DelegationTokenReceiver.class.getClassLoader());
92|        LOG.info(
93|                "Session credentials updated successfully with access key: {} expiration: {}",
94|                credentials.getAccessKeyId(),
95|                credentials.getExpiration());
96|    }
97|
98|    @Nullable
99|    public static Credentials getCredentials() {
100|        return credentials;
101|    }
