67|/** Common utilities to manage SSL transport settings. */
68|public class SSLUtils {
69|
70|    /**
71|     * Creates a factory for SSL Server Sockets from the given configuration. SSL Server Sockets are
72|     * always part of internal communication.
73|     */
74|    public static ServerSocketFactory createSSLServerSocketFactory(Configuration config)
75|            throws Exception {
76|        SSLContext sslContext = createInternalSSLContext(config, false);
77|        if (sslContext == null) {
78|            throw new IllegalConfigurationException("SSL is not enabled");
79|        }
80|
81|        String[] protocols = getEnabledProtocols(config);
82|        String[] cipherSuites = getEnabledCipherSuites(config);
83|
84|        SSLServerSocketFactory factory = sslContext.getServerSocketFactory();
85|        return new ConfiguringSSLServerSocketFactory(factory, protocols, cipherSuites);
86|    }
87|
88|    /**
89|     * Creates a factory for SSL Client Sockets from the given configuration. SSL Client Sockets are
90|     * always part of internal communication.
91|     */
92|    public static SocketFactory createSSLClientSocketFactory(Configuration config)
93|            throws Exception {
94|        SSLContext sslContext = createInternalSSLContext(config, true);
95|        if (sslContext == null) {
96|            throw new IllegalConfigurationException("SSL is not enabled");
97|        }
98|
99|        return sslContext.getSocketFactory();
100|    }
101|
102|    /** Creates a SSLEngineFactory to be used by internal communication server endpoints. */
103|    public static SSLHandlerFactory createInternalServerSSLEngineFactory(final Configuration config)
104|            throws Exception {
105|        SslContext sslContext = createInternalNettySSLContext(config, false);
106|        if (sslContext == null) {
107|            throw new IllegalConfigurationException(
108|                    "SSL is not enabled for internal communication.");
109|        }
110|
111|        return new SSLHandlerFactory(
112|                sslContext,
113|                config.get(SecurityOptions.SSL_INTERNAL_HANDSHAKE_TIMEOUT),
114|                config.get(SecurityOptions.SSL_INTERNAL_CLOSE_NOTIFY_FLUSH_TIMEOUT));
115|    }
116|
117|    /** Creates a SSLEngineFactory to be used by internal communication client endpoints. */
118|    public static SSLHandlerFactory createInternalClientSSLEngineFactory(final Configuration config)
119|            throws Exception {
120|        SslContext sslContext = createInternalNettySSLContext(config, true);
121|        if (sslContext == null) {
122|            throw new IllegalConfigurationException(
123|                    "SSL is not enabled for internal communication.");
124|        }
125|
126|        return new SSLHandlerFactory(
127|                sslContext,
128|                config.get(SecurityOptions.SSL_INTERNAL_HANDSHAKE_TIMEOUT),
129|                config.get(SecurityOptions.SSL_INTERNAL_CLOSE_NOTIFY_FLUSH_TIMEOUT));
130|    }
131|
132|    /**
133|     * Creates a {@link SSLHandlerFactory} to be used by the REST Servers.
134|     *
135|     * @param config The application configuration.
136|     */
137|    public static SSLHandlerFactory createRestServerSSLEngineFactory(final Configuration config)
138|            throws Exception {
139|        ClientAuth clientAuth =
140|                SecurityOptions.isRestSSLAuthenticationEnabled(config)
141|                        ? ClientAuth.REQUIRE
142|                        : ClientAuth.NONE;
143|        SslContext sslContext = createRestNettySSLContext(config, false, clientAuth);
144|        if (sslContext == null) {
145|            throw new IllegalConfigurationException("SSL is not enabled for REST endpoints.");
146|        }
147|
148|        return new SSLHandlerFactory(sslContext, -1, -1);
149|    }
150|
151|    /**
152|     * Creates a {@link SSLHandlerFactory} to be used by the REST Clients.
153|     *
154|     * @param config The application configuration.
155|     */
156|    public static SSLHandlerFactory createRestClientSSLEngineFactory(final Configuration config)
157|            throws Exception {
158|        ClientAuth clientAuth =
159|                SecurityOptions.isRestSSLAuthenticationEnabled(config)
160|                        ? ClientAuth.REQUIRE
161|                        : ClientAuth.NONE;
162|        SslContext sslContext = createRestNettySSLContext(config, true, clientAuth);
163|        if (sslContext == null) {
164|            throw new IllegalConfigurationException("SSL is not enabled for REST endpoints.");
165|        }
166|
167|        return new SSLHandlerFactory(sslContext, -1, -1);
168|    }
169|
170|    private static String[] getEnabledProtocols(final Configuration config) {
171|        checkNotNull(config, "config must not be null");
172|        return config.get(SecurityOptions.SSL_PROTOCOL).split(",");
173|    }
174|
175|    private static String[] getEnabledCipherSuites(final Configuration config) {
176|        checkNotNull(config, "config must not be null");
177|        return config.get(SecurityOptions.SSL_ALGORITHMS).split(",");
178|    }
179|
180|    @VisibleForTesting
181|    static SslProvider getSSLProvider(final Configuration config) {
182|        checkNotNull(config, "config must not be null");
183|        String providerString = config.get(SecurityOptions.SSL_PROVIDER);
184|        if (providerString.equalsIgnoreCase("OPENSSL")) {
185|            if (OpenSsl.isAvailable()) {
186|                return OPENSSL;
187|            } else {
188|                throw new IllegalConfigurationException(
189|                        "openSSL not available", OpenSsl.unavailabilityCause());
190|            }
191|        } else if (providerString.equalsIgnoreCase("JDK")) {
192|            return JDK;
193|        } else {
194|            throw new IllegalConfigurationException("Unknown SSL provider: %s", providerString);
195|        }
196|    }
197|
198|    private static Optional<TrustManagerFactory> getTrustManagerFactory(
199|            Configuration config, boolean internal)
200|            throws KeyStoreException, IOException, NoSuchAlgorithmException, CertificateException {
201|
202|        String trustStoreFilePath =
203|                config.get(
204|                        internal
205|                                ? SecurityOptions.SSL_INTERNAL_TRUSTSTORE
206|                                : SecurityOptions.SSL_REST_TRUSTSTORE,
207|                        config.get(SecurityOptions.SSL_TRUSTSTORE));
208|
209|        String trustStorePassword =
210|                config.get(
211|                        internal
212|                                ? SecurityOptions.SSL_INTERNAL_TRUSTSTORE_PASSWORD
213|                                : SecurityOptions.SSL_REST_TRUSTSTORE_PASSWORD,
214|                        config.get(SecurityOptions.SSL_TRUSTSTORE_PASSWORD));
215|        // do not use getAndCheckOption here as there is no fallback option and a default is
216|        // specified
217|        String truststoreType =
218|                internal
219|                        ? config.get(SecurityOptions.SSL_INTERNAL_TRUSTSTORE_TYPE)
220|                        : config.get(SecurityOptions.SSL_REST_TRUSTSTORE_TYPE);
221|
222|        // Support for the REST client connecting to external HTTPS URLs to fall back to the
223|        // default trust store of the provider (JDK).
224|        if (!internal && trustStoreFilePath == null && trustStorePassword == null) {
225|            return Optional.empty();
226|        } else if (trustStoreFilePath == null) {
227|            throw new IllegalConfigurationException(
228|                    "The config option "
229|                            + SecurityOptions.SSL_INTERNAL_TRUSTSTORE.key()
230|                            + " or "
231|                            + SecurityOptions.SSL_TRUSTSTORE.key()
232|                            + " is missing.");
233|        } else if (trustStorePassword == null) {
234|            throw new IllegalConfigurationException(
235|                    "The config option "
236|                            + SecurityOptions.SSL_INTERNAL_TRUSTSTORE_PASSWORD.key()
237|                            + " or "
238|                            + SecurityOptions.SSL_TRUSTSTORE_PASSWORD
239|                            + " is missing.");
240|        }
241|
242|        KeyStore trustStore = KeyStore.getInstance(truststoreType);
243|        try (InputStream trustStoreFile =
244|                Files.newInputStream(new File(trustStoreFilePath).toPath())) {
245|            trustStore.load(trustStoreFile, trustStorePassword.toCharArray());
246|        }
247|
248|        String certFingerprint =
249|                config.get(
250|                        internal
251|                                ? SecurityOptions.SSL_INTERNAL_CERT_FINGERPRINT
252|                                : SecurityOptions.SSL_REST_CERT_FINGERPRINT);
253|
254|        TrustManagerFactory tmf;
255|        if (StringUtils.isNullOrWhitespaceOnly(certFingerprint)) {
256|            tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
257|        } else {
258|            tmf = new FingerprintTrustManagerFactory(certFingerprint.split(","));
259|        }
260|
261|        tmf.init(trustStore);
262|
263|        return Optional.of(tmf);
264|    }
265|
266|    private static KeyManagerFactory getKeyManagerFactory(
267|            Configuration config, boolean internal, SslProvider provider)
268|            throws KeyStoreException,
269|                    IOException,
270|                    NoSuchAlgorithmException,
271|                    CertificateException,
272|                    UnrecoverableKeyException {
273|        String keystoreFilePath =
274|                getAndCheckOption(
275|                        config,
276|                        internal
277|                                ? SecurityOptions.SSL_INTERNAL_KEYSTORE
278|                                : SecurityOptions.SSL_REST_KEYSTORE,
279|                        SecurityOptions.SSL_KEYSTORE);
280|
281|        String keystorePassword =
282|                getAndCheckOption(
283|                        config,
284|                        internal
285|                                ? SecurityOptions.SSL_INTERNAL_KEYSTORE_PASSWORD
286|                                : SecurityOptions.SSL_REST_KEYSTORE_PASSWORD,
287|                        SecurityOptions.SSL_KEYSTORE_PASSWORD);
288|
289|        String certPassword =
290|                getAndCheckOption(
291|                        config,
292|                        internal
293|                                ? SecurityOptions.SSL_INTERNAL_KEY_PASSWORD
294|                                : SecurityOptions.SSL_REST_KEY_PASSWORD,
295|                        SecurityOptions.SSL_KEY_PASSWORD);
296|
297|        // do not use getAndCheckOption here as there is no fallback option and a default is
298|        // specified
299|        String keystoreType =
300|                internal
301|                        ? config.get(SecurityOptions.SSL_INTERNAL_KEYSTORE_TYPE)
302|                        : config.get(SecurityOptions.SSL_REST_KEYSTORE_TYPE);
303|
304|        KeyStore keyStore = KeyStore.getInstance(keystoreType);
305|        try (InputStream keyStoreFile = Files.newInputStream(new File(keystoreFilePath).toPath())) {
306|            keyStore.load(keyStoreFile, keystorePassword.toCharArray());
307|        }
308|
309|        final KeyManagerFactory kmf;
310|        if (provider == OPENSSL || provider == OPENSSL_REFCNT) {
311|            kmf = new OpenSslX509KeyManagerFactory();
312|        } else {
313|            kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
314|        }
315|        kmf.init(keyStore, certPassword.toCharArray());
316|
317|        return kmf;
318|    }
319|
320|    /**
321|     * Creates the SSL Context for internal SSL, if internal SSL is configured. For internal SSL,
