343|     * Creates the SSL Context for internal SSL, if internal SSL is configured. For internal SSL,
344|     * the client and server side configuration are identical, because of mutual authentication.
345|     */
346|    @Nullable
347|    private static SslContext createInternalNettySSLContext(
348|            Configuration config, boolean clientMode, SslProvider provider) throws Exception {
349|        checkNotNull(config, "config");
350|
351|        if (!SecurityOptions.isInternalSSLEnabled(config)) {
352|            return null;
353|        }
354|
355|        String[] sslProtocols = getEnabledProtocols(config);
356|        List<String> ciphers = Arrays.asList(getEnabledCipherSuites(config));
357|        int sessionCacheSize = config.get(SecurityOptions.SSL_INTERNAL_SESSION_CACHE_SIZE);
358|        int sessionTimeoutMs = config.get(SecurityOptions.SSL_INTERNAL_SESSION_TIMEOUT);
359|
360|        KeyManagerFactory kmf = getKeyManagerFactory(config, true, provider);
361|        ClientAuth clientAuth = ClientAuth.REQUIRE;
362|
363|        final SslContextBuilder sslContextBuilder;
364|        if (clientMode) {
365|            sslContextBuilder = SslContextBuilder.forClient().keyManager(kmf);
366|        } else {
367|            sslContextBuilder = SslContextBuilder.forServer(kmf);
368|        }
369|
370|        Optional<TrustManagerFactory> tmf = getTrustManagerFactory(config, true);
371|        tmf.map(sslContextBuilder::trustManager);
372|
373|        return sslContextBuilder
374|                .sslProvider(provider)
375|                .protocols(sslProtocols)
376|                .ciphers(ciphers)
377|                .clientAuth(clientAuth)
378|                .sessionCacheSize(sessionCacheSize)
379|                .sessionTimeout(sessionTimeoutMs / 1000)
380|                // Internal SSL uses one shared, mutually-trusted certificate across every node
381|                // (see docs/deployment/security/security-ssl.md), so it must not be required to
382|                // also match each peer's hostname. Explicitly disabled because Netty enables
383|                // endpoint identification by default from 4.2 onward (both JDK and OpenSSL
384|                // providers), which would otherwise break every connection whose resolved
385|                // hostname isn't covered by the shared certificate.
386|                .endpointIdentificationAlgorithm(null)
387|                .build();
388|    }
