416|     * client and the server side configuration are identical.
417|     */
418|    @Nullable
419|    public static SslContext createRestNettySSLContext(
420|            Configuration config, boolean clientMode, ClientAuth clientAuth, SslProvider provider)
421|            throws Exception {
422|        checkNotNull(config, "config");
423|
424|        if (!SecurityOptions.isRestSSLEnabled(config)) {
425|            return null;
426|        }
427|
428|        String[] sslProtocols = getEnabledProtocols(config);
429|        List<String> ciphers = Arrays.asList(getEnabledCipherSuites(config));
430|
431|        final SslContextBuilder sslContextBuilder;
432|        if (clientMode) {
433|            sslContextBuilder = SslContextBuilder.forClient();
434|            if (clientAuth != ClientAuth.NONE) {
435|                KeyManagerFactory kmf = getKeyManagerFactory(config, false, provider);
436|                sslContextBuilder.keyManager(kmf);
437|            }
438|            sslContextBuilder.endpointIdentificationAlgorithm(
439|                    config.get(SecurityOptions.SSL_REST_VERIFY_HOSTNAME) ? "HTTPS" : null);
440|        } else {
441|            KeyManagerFactory kmf = getKeyManagerFactory(config, false, provider);
442|            sslContextBuilder = SslContextBuilder.forServer(kmf);
443|        }
444|
445|        if (clientMode || clientAuth != ClientAuth.NONE) {
446|            Optional<TrustManagerFactory> tmf = getTrustManagerFactory(config, false);
447|            tmf.map(
448|                    // Use specific ciphers and protocols if SSL is configured with self-signed
449|                    // certificates (user-supplied truststore)
450|                    tm ->
451|                            sslContextBuilder
452|                                    .trustManager(tm)
453|                                    .protocols(sslProtocols)
454|                                    .ciphers(ciphers)
455|                                    .clientAuth(clientAuth));
456|        }
457|
458|        return sslContextBuilder.sslProvider(provider).build();
459|    }
